#include <bits/stdc++.h>
#include <cfenv>
#include <cmath>
#pragma STDC FENV_ACCESS ON
using namespace std;
struct Term{array<int,4> e; double c;};struct Box{array<double,3> l,u;double ub;};struct Cmp{bool operator()(Box const&a,Box const&b)const{return a.ub<b.ub;}};
static const Term T[]={{{{2,2,0,0}},0.04822142787987652},{{{2,0,2,0}},0.05333608476307321},{{{1,2,1,0}},0.11385707390148081},{{{1,1,1,1}},0.3428679997023158},{{{1,0,3,0}},0.06204319383393708},{{{0,2,2,0}},0.0656356460216043},{{{0,2,0,2}},0.13577211811522824},{{{0,1,2,1}},0.2940921349879693},{{{0,0,4,0}},0.017687575726200243},{{{0,0,2,2}},0.1460014318816216}};
inline double mulup(double a,double b){volatile double x=a*b;return x;}inline double addup(double a,double b){volatile double x=a+b;return x;}inline double sqrto(double a){volatile double x=sqrt(a);return x;}inline double ph(double y,int e){if(e==0)return 1.;if(y<=0)return 0.;if(e==1)return sqrto(y);if(e==2)return y;if(e==3)return mulup(y,sqrto(y));if(e==4)return mulup(y,y);abort();}
inline bool derive(const Box&b,array<double,4>&l,array<double,4>&u){for(int i=0;i<3;i++){l[i]=b.l[i];u[i]=b.u[i];}double sl=b.l[0]+b.l[1]+b.l[2],su=b.u[0]+b.u[1]+b.u[2];if(sl>1.)return false;l[3]=max(0.,1.-su);u[3]=min(1.,1.-sl);return l[3]<=u[3];}
double mono(const Term&t,const array<double,4>&l,const array<double,4>&u){double box=1,inactive=0;for(int i=0;i<4;i++){if(t.e[i])box=mulup(box,ph(u[i],t.e[i]));else inactive+=l[i];}double S=1-inactive;if(S<0)return 0.;double am=1;for(int i=0;i<4;i++)if(t.e[i])am=mulup(am,ph(S*.25*t.e[i],t.e[i]));return min(box,am);}
double UB(const Box&b){array<double,4>l,u;if(!derive(b,l,u))return -INFINITY;double s=0;for(auto&t:T)s=addup(s,mulup(t.c,mono(t,l,u)));return s;}
int main(int argc,char**argv){if(argc!=7){cerr<<"usage l0 u0 l1 u1 l2 u2\n";return 2;}fesetround(FE_UPWARD);const double best=0.0932487158813161;Box root;for(int i=0;i<3;i++){root.l[i]=atof(argv[1+2*i]);root.u[i]=atof(argv[2+2*i]);}root.ub=UB(root);priority_queue<Box,vector<Box>,Cmp>pq;if(root.ub>=best)pq.push(root);long long n=0;auto st=chrono::steady_clock::now();while(!pq.empty()){Box b=pq.top();pq.pop();if(++n>50000000){cout<<"INCOMPLETE top "<<setprecision(17)<<b.ub<<" nodes "<<n<<" heap "<<pq.size()<<"\n";return 3;}int k=0;double w=-1;for(int i=0;i<3;i++){double z=b.u[i]-b.l[i];if(z>w){w=z;k=i;}}if(w<ldexp(1.0,-50)){cout<<"UNRESOLVED tiny top "<<setprecision(17)<<b.ub<<"\n";return 4;}double mid=(b.l[k]+b.u[k])*.5;for(int side=0;side<2;side++){Box q=b;if(!side)q.u[k]=mid;else q.l[k]=mid;q.ub=UB(q);if(q.ub>=best)pq.push(q);}if(n%5000000==0)cerr<<n<<" top "<<(pq.empty()?best:pq.top().ub)<<" heap "<<pq.size()<<" sec "<<chrono::duration<double>(chrono::steady_clock::now()-st).count()<<"\n";}cout<<"CERTIFIED_BELOW_BEST nodes "<<n<<" sec "<<chrono::duration<double>(chrono::steady_clock::now()-st).count()<<"\n";}
